"""Recommendation domain shared models."""

from datetime import datetime
from decimal import Decimal
from uuid import UUID
from pydantic import Field, field_validator
from Shared.enums import RecommendationStatus, TradeDirection
from .common import AlphaGridBaseModel
from .evidence import Evidence


class Opportunity(AlphaGridBaseModel):
    """Trading opportunity generated by scanning strategies."""

    opportunity_id: UUID
    symbol: str = Field(..., min_length=1)
    strategy: str = Field(..., min_length=1)
    direction: TradeDirection
    opportunity_score: Decimal
    created_at: datetime
    status: str = Field(..., min_length=1)

    @field_validator("opportunity_score", mode="after")
    @classmethod
    def validate_opportunity_score(cls, v: Decimal) -> Decimal:
        """Ensure opportunity score is non-negative."""
        if v < Decimal("0"):
            raise ValueError("Opportunity score must be non-negative.")
        return v


class Recommendation(AlphaGridBaseModel):
    """Authoritative trading recommendation composed from opportunities and evidence."""

    recommendation_id: UUID
    opportunity_id: UUID
    symbol: str = Field(..., min_length=1)
    strategy: str = Field(..., min_length=1)
    direction: TradeDirection
    entry_price: Decimal
    stop_loss: Decimal
    targets: list[Decimal] = Field(..., min_items=1)
    confidence: Decimal
    opportunity_score: Decimal
    status: RecommendationStatus
    timestamp: datetime
    evidence: list[Evidence] = Field(default_factory=list)

    @field_validator("confidence", mode="after")
    @classmethod
    def validate_confidence(cls, v: Decimal) -> Decimal:
        """Ensure confidence is between 0.0 and 1.0 (inclusive)."""
        if v < Decimal("0") or v > Decimal("1"):
            raise ValueError("Confidence must be between 0.0 and 1.0.")
        return v

    @field_validator("entry_price", "stop_loss", mode="after")
    @classmethod
    def validate_positive_prices(cls, v: Decimal) -> Decimal:
        """Ensure entry price and stop loss are positive."""
        if v <= Decimal("0"):
            raise ValueError("Price values must be greater than zero.")
        return v

    @field_validator("targets", mode="after")
    @classmethod
    def validate_targets(cls, v: list[Decimal]) -> list[Decimal]:
        """Ensure all target prices are positive."""
        for target in v:
            if target <= Decimal("0"):
                raise ValueError("Target prices must be greater than zero.")
        return v

    @field_validator("opportunity_score", mode="after")
    @classmethod
    def validate_opportunity_score(cls, v: Decimal) -> Decimal:
        """Ensure opportunity score is non-negative."""
        if v < Decimal("0"):
            raise ValueError("Opportunity score must be non-negative.")
        return v
